const{sql}=require('../../lib/db');const{withErrors,ok,fail,requireMethod,getBody}=require('../../lib/http');const{requireUser}=require('../../lib/auth');const roomStore=require('../../lib/roomStore');const{broadcast}=require('../../lib/pusherServer');
const ALLOWED=new Set(['😂','💀','🤡','😭','🤨']);
module.exports=withErrors(async(req,res)=>{if(!requireMethod(req,res,'POST'))return;const user=await requireUser(req,res);if(!user)return;const{code,emoji}=getBody(req);if(!code||!ALLOWED.has(emoji))return fail(res,400,'Reação inválida.');const room=await roomStore.loadRoom(code);if(!room)return fail(res,404,'Sala não encontrada.');const player=room.players.get(String(user.id));if(!player||player.active===false)return fail(res,403,'Apenas jogadores ativos podem reagir.');await sql`INSERT INTO user_reactions(room_code,user_id,emoji) VALUES(${room.code},${user.id},${emoji})`;await broadcast(room.code,'reaction',{emoji,userId:user.id,nickname:player.nickname,avatarData:player.avatarData||null});ok(res);});
